function f(t){return t>=39?9:t>=37?8.5:t>=35?8:t>=33?7.5:t>=30?7:t>=27?6.5:t>=23?6:t>=20?5.5:t>=16?5:t>=13?4.5:t>=10?4:t>=8?3.5:t>=6?3:2.5}function u(t,n){if(t.type==="fill-blank")return n.trim().toLowerCase()===String(t.answer).trim().toLowerCase();if(t.type==="multi-select"&&Array.isArray(t.answer)){const e=new Set(n.split(",").filter(Boolean).map(r=>Number(r))),i=new Set(t.answer);return e.size===i.size&&[...i].every(r=>e.has(r))}return n===String(t.answer)}function s(t,n){if(t.type!=="multi-select"||!Array.isArray(t.answer))return u(t,n)?1:0;const e=new Set(n.split(",").filter(Boolean).map(a=>Number(a))),i=new Set(t.answer);let r=0;for(const a of e)i.has(a)&&r++;return r}function o(t){const n=Math.floor(t/60),e=t%60;return`${String(n).padStart(2,"0")}:${String(e).padStart(2,"0")}`}export{f as bandScore,o as formatCountdown,u as isCorrect,s as multiSelectScore};
